macro_rules! deflateInit_ {
    () => {
        # [doc = " Initializes the state for compression"] # [doc = ""] # [doc = "  The stream's `zalloc`, `zfree` and `opaque` fields must be initialized before by the caller."] # [doc = "  If `zalloc` and `zfree` are set to `NULL`, [`deflateInit_`] updates them to use default allocation functions."] # [doc = "  The `total_in`, `total_out`, `adler`, and `msg` fields are initialized."] # [doc = ""] # [doc = " The compression level must be [`Z_DEFAULT_COMPRESSION`], or between `0` and `9`:"] # [doc = ""] # [doc = " - level `0` gives no compression at all (the input data is simply copied a block at a time)"] # [doc = " - level `1` gives best speed"] # [doc = " - level `9` gives best compression"] # [doc = " - [`Z_DEFAULT_COMPRESSION`] requests a default compromise between speed and compression (currently equivalent to level `6`)."] # [doc = ""] # [doc = " A call to [`deflateInit_`] is equivalent to [`deflateInit2_`] where:"] # [doc = ""] # [doc = " - `method` is `8` (deflate)"] # [doc = " - `windowBits` is `15`"] # [doc = " - `memLevel` is `8`"] # [doc = " - `strategy` is `0` (default)"] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " - [`Z_OK`] if success"] # [doc = " - [`Z_MEM_ERROR`] if there was not enough memory"] # [doc = " - [`Z_VERSION_ERROR`] if the zlib library version is incompatible with the version assumed by the caller"] # [doc = " - [`Z_STREAM_ERROR`] if a parameter is invalid, such as a null pointer to the structure"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must guarantee that"] # [doc = ""] # [doc = " * Either"] # [doc = "     - `strm` is `NULL`"] # [doc = "     - `strm` satisfies the requirements of `&mut *strm`"] # [doc = " * Either"] # [doc = "     - `version` is NULL"] # [doc = "     - `version` satisfies the requirements of [`core::ffi::CStr::from_ptr`]"] # [doc = " * If `strm` is not `NULL`, the following fields contain valid values"] # [doc = "     - `zalloc`"] # [doc = "     - `zfree`"] # [doc = "     - `opaque`"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use core::mem::MaybeUninit;"] # [doc = " use libz_rs_sys::{z_stream, deflateInit_, zlibVersion, Z_OK};"] # [doc = ""] # [doc = " // the zalloc and zfree fields are initialized as zero/NULL."] # [doc = " // `deflateInit_` will set a default allocation  and deallocation function."] # [doc = " let mut strm = MaybeUninit::zeroed();"] # [doc = ""] # [doc = " let err = unsafe {"] # [doc = "     deflateInit_("] # [doc = "         strm.as_mut_ptr(),"] # [doc = "         6,"] # [doc = "         zlibVersion(),"] # [doc = "         core::mem::size_of::<z_stream>() as _,"] # [doc = "     )"] # [doc = " };"] # [doc = " assert_eq!(err, Z_OK);"] # [doc = ""] # [doc = " // the stream is now fully initialized. Prefer `assume_init_mut` over"] # [doc = " // `assume_init` so the stream does not get moved."] # [doc = " let strm = unsafe { strm.assume_init_mut() };"] # [doc = " ```"] # [cfg_attr (feature = "export-symbols" , export_name = prefix ! (deflateInit_))] pub unsafe extern "C-unwind" fn deflateInit_ (strm : z_streamp , level : c_int , version : * const c_char , stream_size : c_int ,) -> c_int { let config = DeflateConfig :: new (level) ; unsafe { deflateInit2_ (strm , level , config . method as c_int , config . window_bits , config . mem_level , config . strategy as c_int , version , stream_size ,) } }
    };
}

deflateInit_!()